const out = process.argv[2];
if (!out) { console.error("usage: node build.mjs <out.nbt>"); process.exit(2); }

const g = new Grid(SITE_SIZE, { dataVersion: DATA_VERSION });
g.fill([0, 0, 0], [43, 0, 31], "grass_block");

runParts(g, [
  ["main shell", mainShell.build],
